/*
 * macaddr.c - EXPERIMENTAL: the "MAC address" setting (kernel/macaddr.c).
 *
 * Stock uses the console's own address. Custom uses a saved one, which is
 * either typed in, or generated by Randomize (the console's own first three
 * bytes, the maker, plus three random bytes). Switching to Custom generates a
 * new one. Every change drops the Wi-Fi link, sends the address to the chip and
 * rejoins, since the access point knows the console by its address.
 *
 * The chip comes back on its factory address at every power-up (Wi-Fi off/on,
 * resume) and the driver no longer asks it, so a watcher re-sends the custom
 * address after each one, and boot sends it once the link is up. In Default,
 * a power-up after a custom address leaves the driver's copies on the custom
 * one, so the watcher sends the console's own address once then.
 *
 * A console that stays on Default never loads the kernel hooks and runs no
 * watcher thread: its own address is read from SceNet by the keepwifi
 * network thread (wq_mac_net_tick). The watcher starts with Custom at boot,
 * or with the first change. Nothing is sent while the radio is off or
 * power-cycling, or the Vita is going to sleep; a refused change is retried
 * a few times, further apart each time, then left until the next power-up.
 *
 * Commands (dispatch.c, from :1339; the Settings page queues them for the
 * watcher thread, wq_mac_queue, so the keepwifi tick never waits on them):
 *   mac status | stock | custom | random | set <addr>
 * The chosen mode and address are saved through wq_settings_note as
 * "mac state <0|1> <12 hex>"; the console's own address as "mac factory <12 hex>".
 */
#include <psp2/kernel/processmgr.h>   /* sceKernelGetProcessTimeWide */
#include <psp2/kernel/threadmgr.h>    /* threads, mutex               */
#include <psp2/kernel/rng.h>          /* sceKernelGetRandomNumber     */
#include <psp2/net/net.h>             /* sceNetGetMacAddress          */
#include <psp2/net/netctl.h>          /* sceNetCtlInetGet*            */
#include <string.h>

#include "macaddr.h"
#include "rxcycle.h"
#include "rxpreset.h"                 /* rxpreset_boot_state */
#include "netjoin.h"
#include "keepwifi.h"                 /* hold reconnects, sleep in progress */
#include "dispatch.h"                 /* wq_dispatch_exec (queued commands) */
#include "settings_entry.h"           /* wq_settings_note_mac */
#include "log.h"
#include "../include/wifiturbo.h"
#include "../include/wifiturbo_kernel_api.h"

extern int sceWlanGetConfiguration(void);   /* NID 0x70AF9BD6; &9 = radio on */

#define MAC_BOOT_WAIT_S   30                /* boot: wait this long for a power-up */
#define MAC_CTX_POLLS     20                /* RSSI reads to show the driver ctx */
#define MAC_RETRIES       6                 /* refused changes retried this often */
#define MAC_RETRY_MAX_S   60                /* 5, 10, 20, 40, 60, 60 s apart      */
#define MAC_QUEUE         8                 /* Settings commands waiting          */
#define MAC_SET_WINDOW_US (8 * 1000 * 1000) /* chip busy/initialising: retry this long */

static int hexval(char c)
{
	if (c >= '0' && c <= '9') return c - '0';
	if (c >= 'a' && c <= 'f') return c - 'a' + 10;
	if (c >= 'A' && c <= 'F') return c - 'A' + 10;
	return -1;
}

int wq_mac_parse(const char *s, uint8_t mac[6], int *why)
{
	int n = 0;
	uint8_t b[6];
	*why = 1;
	for (; *s && *s != ' '; s++) {
		if (*s == ':' || *s == '-' || *s == '.')
			continue;
		int v = hexval(*s);
		if (v < 0 || n >= 12)
			return -1;
		if (n & 1) b[n / 2] = (uint8_t)(b[n / 2] << 4 | v);
		else       b[n / 2] = (uint8_t)v;
		n++;
	}
	if (n != 12)
		return -1;
	if (b[0] & 1) { *why = 2; return -1; }
	int zero = 1, ff = 1;
	for (int i = 0; i < 6; i++) {
		if (b[i])         zero = 0;
		if (b[i] != 0xFF) ff = 0;
	}
	if (zero || ff) { *why = 3; return -1; }
	memcpy(mac, b, 6);
	*why = 0;
	return 0;
}

static const char *const k_why[4] = {
	"", "not 12 hex digits", "group (multicast) address - first byte must be even",
	"all-zero or broadcast address",
};

static char *put(char *p, char *end, const char *s)
{
	while (*s && p < end - 1) *p++ = *s++;
	*p = 0;
	return p;
}

static char *put_u(char *p, char *end, unsigned v)
{
	char t[12]; int n = 0;
	if (!v) t[n++] = '0';
	while (v) { t[n++] = (char)('0' + v % 10); v /= 10; }
	while (n && p < end - 1) *p++ = t[--n];
	*p = 0;
	return p;
}

static char *put_hex(char *p, char *end, unsigned v)
{
	static const char hx[] = "0123456789abcdef";
	int sh = 28;
	while (sh > 0 && !((v >> sh) & 15)) sh -= 4;
	for (; sh >= 0 && p < end - 1; sh -= 4)
		*p++ = hx[(v >> sh) & 15];
	*p = 0;
	return p;
}

static char *put_mac_sep(char *p, char *end, const uint8_t *m, int sep)
{
	const char *h = "0123456789ABCDEF";
	for (int i = 0; i < 6; i++) {
		if (i && sep && p < end - 1) *p++ = ':';
		if (p < end - 2) { *p++ = h[m[i] >> 4]; *p++ = h[m[i] & 15]; }
	}
	*p = 0;
	return p;
}

static char *put_mac(char *p, char *end, const uint8_t *m)
{
	return put_mac_sep(p, end, m, 1);
}

static void split(const uint8_t *m, unsigned *m0, unsigned *m1)
{
	*m0 = m[0] | m[1] << 8 | m[2] << 16 | (unsigned)m[3] << 24;
	*m1 = m[4] | m[5] << 8;
}

static void join(uint8_t *m, unsigned m0, unsigned m1)
{
	m[0] = (uint8_t)m0; m[1] = (uint8_t)(m0 >> 8); m[2] = (uint8_t)(m0 >> 16);
	m[3] = (uint8_t)(m0 >> 24); m[4] = (uint8_t)m1; m[5] = (uint8_t)(m1 >> 8);
}

/* The console's first three bytes + three random ones, never its own address.
 * Also used by the Settings page, so it knows the new address at once. */
void wq_mac_random(uint8_t m[6], const uint8_t factory[6])
{
	memcpy(m, factory, 3);
	do {
		uint32_t x = 0;
		if (sceKernelGetRandomNumber(&x, sizeof(x)) < 0) {   /* clock fallback */
			x = (uint32_t)sceKernelGetProcessTimeWide() * 2654435761u;
			x ^= x >> 15; x *= 0x2C1B3C6Du; x ^= x >> 12;
		}
		m[3] = (uint8_t)x; m[4] = (uint8_t)(x >> 8); m[5] = (uint8_t)(x >> 16);
	} while (!memcmp(m, factory, 6));
}

/* wqMacAddr with its WQ_ERR_* restored (wq_kret). */
static int kmac(int op, unsigned m0, unsigned m1, WqMacStatus *st)
{
	return wq_kret(wqMacAddr(op, m0, m1, st));
}

static int netctl_state(void)
{
	int st = -1;
	return sceNetCtlInetGetState(&st) == 0 ? st : -1;
}

static int radio_on(void)
{
	return (sceWlanGetConfiguration() & 9) != 0;
}

/* Safe to start a driver call: the radio is on, no power-cycle is turning it
 * (or Bluetooth) off or back on, and the Vita is not going to sleep. The
 * kernel also refuses while the chip is powering up (WQ_ERR_BUSY). */
static int can_send(void)
{
	return radio_on() && rxcycle_settled() && !keepwifi_power_busy();
}

/* Worth trying again later (retry_tick). */
static int retryable(int r)
{
	return r == WQ_ERR_CHIP || r == WQ_ERR_BUSY || r == WQ_ERR_NOT_READY;
}

/* Take the link down and keep it down: 0 once netctl reports 0, else
 * WQ_ERR_NOT_READY (the SET never goes out under a live or starting join). */
static int link_down(void)
{
	for (int tries = 0; tries < 2; tries++) {
		if (netctl_state() <= 0)                 /* down (or netctl unreadable) */
			return WQ_OK;
		wq_net_disconnect();
		for (int i = 0; i < 40 && netctl_state() > 0; i++)
			sceKernelDelayThread(200 * 1000);
	}
	if (netctl_state() <= 0)
		return WQ_OK;
	WQ_LOGW("mac: netctl still reports state %d after the disconnect - not sending",
	        netctl_state());
	return WQ_ERR_NOT_READY;
}

/* ---- state ---------------------------------------------------------------- */

static SceUID            g_mtx = -1;
static volatile int      g_mode;               /* 0 stock, 1 custom (saved)   */
static uint8_t           g_custom[6];
static uint8_t           g_saved_factory[6];
static volatile uint32_t g_applied_powerups;
static volatile int      g_retry;              /* last SET failed: retry      */
static volatile int      g_applying;           /* inside apply()              */
static int               g_retry_n;            /* retries so far              */
static SceInt64          g_retry_at;           /* next one, process time (us) */
static char              g_queue[MAC_QUEUE][WQ_UI_CMD_MAX];
static volatile unsigned g_q_head, g_q_tail;
static volatile int      g_watch_started, g_job_busy;
static uint8_t           g_job_mac[6];
static volatile int      g_job_boot;
static volatile int      g_boot_rx_cycle;      /* the RX buffer preset cycles at boot */
static volatile int      g_fast;               /* boot: watch the power-up closely  */

static void save_state(void)
{
	char line[40], *p = line, *end = line + sizeof(line);
	p = put(p, end, g_mode ? "mac state 1 " : "mac state 0 ");
	put_mac_sep(p, end, g_custom, 0);
	wq_settings_note_mac(line);
}

/* A new change, or the mode moved on: start the retry count again. */
static void retry_reset(void)
{
	g_retry = 0;
	g_retry_n = 0;
	g_retry_at = 0;
}

/* The kernel only learns the driver ctx once a chip command has gone through
 * the send helper. Reading the RSSI makes the driver send one. Installs the
 * hooks if they are not in yet. */
static int ensure_ctx(WqMacStatus *st)
{
	for (int i = 0; i < MAC_CTX_POLLS; i++) {
		if (kmac(WQ_MAC_OP_HOOK, 0, 0, st) == WQ_OK && st->ctx_seen)
			return WQ_OK;
		SceNetCtlInfo info;
		sceNetCtlInetGetInfo(SCE_NETCTL_INFO_GET_RSSI_DBM, &info);
		sceKernelDelayThread(500 * 1000);
	}
	return WQ_ERR_NOT_READY;
}

/* Remember the console's own address (shown on the Settings page while the
 * mode is Stock, and the base for Randomize). */
static void note_factory_mac(const uint8_t *f)
{
	if (!memcmp(f, g_saved_factory, 6))
		return;
	memcpy(g_saved_factory, f, 6);
	char line[40], *p = line, *end = line + sizeof(line);
	p = put(p, end, "mac factory ");
	put_mac_sep(p, end, f, 0);
	wq_settings_note_mac(line);
}

static void note_factory(const WqMacStatus *st)
{
	if (st->have_factory)
		note_factory_mac(st->factory);
}

/* Drop the link, SET the address, rejoin. Serialised. The reconnect watcher
 * is held off meanwhile, so nothing rejoins on the old address mid-change. */
static int apply(const uint8_t *m, const char *why)
{
	WqMacStatus st;
	int tries = 0;
	memset(&st, 0, sizeof(st));
	if (g_mtx >= 0) sceKernelLockMutex(g_mtx, 1, NULL);
	g_applying = 1;
	int r = can_send() ? ensure_ctx(&st) : WQ_ERR_NOT_READY;
	if (r == WQ_OK) {
		note_factory(&st);
		keepwifi_hold_reconnect(1);
		unsigned m0, m1;
		split(m, &m0, &m1);
		/* Only a chip that is busy or still initialising is retried here, for
		 * MAC_SET_WINDOW_US; a refusal (CHIP) goes to retry_tick. The link is
		 * checked down before every attempt: SceShell may start its own join
		 * meanwhile, and the address must not change under an association. */
		SceInt64 until = (SceInt64)sceKernelGetProcessTimeWide() + MAC_SET_WINDOW_US;
		for (;;) {
			if (!can_send()) {
				r = WQ_ERR_NOT_READY;               /* radio off, cycling, or sleeping */
				break;
			}
			r = link_down();
			if (r != WQ_OK)
				break;
			r = kmac(WQ_MAC_OP_SET, m0, m1, &st);
			tries++;
			if ((r != WQ_ERR_BUSY && r != WQ_ERR_NOT_READY) ||
			    (SceInt64)sceKernelGetProcessTimeWide() >= until)
				break;
			sceKernelDelayThread(250 * 1000);
		}
		keepwifi_hold_reconnect(0);
		/* Kick a join: after a wake or radio cycle the shell's own retry is
		 * slower (5 s rejoin, 12 s IcmConnect); IcmConnect is ignored while a
		 * join is already under way. Not while the radio is off on purpose. */
		if (can_send())
			wq_net_icm_connect();
		if (r == WQ_OK) {
			g_applied_powerups = st.powerups;
			retry_reset();
		} else {
			g_retry = retryable(r);
		}
	} else if (retryable(r)) {
		g_retry = 1;
	}
	g_applying = 0;
	if (g_mtx >= 0) sceKernelUnlockMutex(g_mtx, 1);
	char line[200], *p = line, *end = line + sizeof(line);
	p = put(p, end, "mac: ");      p = put(p, end, why);
	p = put(p, end, " ");          p = put_mac(p, end, m);
	p = put(p, end, r == WQ_OK ? " OK" : " FAILED r=");
	if (r != WQ_OK) { p = put(p, end, r < 0 ? "-" : ""); p = put_u(p, end, (unsigned)(r < 0 ? -r : r)); }
	p = put(p, end, " tries ");    p = put_u(p, end, (unsigned)tries);
	p = put(p, end, " (rc ");      p = put_hex(p, end, (unsigned)st.last_rc);
	p = put(p, end, " chip ");     p = put_mac(p, end, st.live);
	p = put(p, end, " ctl ");      p = put_u(p, end, st.ctl_check);
	p = put(p, end, " walk ");     p = put_u(p, end, st.chain);
	put(p, end, ")");
	if (r == WQ_OK) WQ_LOGI("%s", line); else WQ_LOGW("%s", line);
	return r;
}

/* Re-send the custom address after every chip power-up. The counter is a hook
 * on the driver's post-firmware init; reading it sends nothing to the chip. */
static int factory(uint8_t *out);
static void watch_start(void);

/* Settings commands, run here rather than on the keepwifi tick that drains
 * the mailbox: a change can take seconds (ensure_ctx, the SET retries). */
static void run_queue(void)
{
	while (g_q_tail != g_q_head) {
		char line[WQ_UI_CMD_MAX], rep[160];
		memcpy(line, g_queue[g_q_tail % MAC_QUEUE], sizeof(line));
		g_q_tail = g_q_tail + 1;
		wq_dispatch_exec(line, rep, sizeof(rep));
	}
}

/* A refused change, retried MAC_RETRIES times, further apart each time: the
 * saved setting must not claim an address the chip is not using, but a
 * driver that keeps refusing must not have the link dropped forever. */
static void retry_tick(void)
{
	SceInt64 now = (SceInt64)sceKernelGetProcessTimeWide();
	if (g_retry_at == 0) {
		int s = 5 << g_retry_n;
		g_retry_at = now + (SceInt64)(s < MAC_RETRY_MAX_S ? s : MAC_RETRY_MAX_S) * 1000000;
		return;
	}
	if (now < g_retry_at || !can_send())
		return;
	if (g_retry_n >= MAC_RETRIES) {
		WQ_LOGW("mac: still refused after %d retries - left until the next power-up or change",
		        MAC_RETRIES);
		retry_reset();
		return;
	}
	g_retry_n++;
	g_retry_at = 0;
	uint8_t f[6];
	int n = g_retry_n;
	g_retry = 0;
	if (g_mode == 1)
		apply(g_custom, "retry");
	else if (factory(f) == WQ_OK)
		apply(f, "retry stock");
	g_retry_n = g_retry ? n : 0;              /* apply cleared it on success */
}

/* Without the hooks no address was ever set this boot, so SceNet's is the
 * console's own. */
static void factory_from_scenet(void)
{
	SceNetEtherAddr na;
	uint8_t probe[6];
	int why;
	char t12[13];
	memset(&na, 0, sizeof(na));
	if (sceNetGetMacAddress(&na, 0) >= 0) {
		put_mac_sep(t12, t12 + sizeof(t12), na.data, 0);
		if (wq_mac_parse(t12, probe, &why) == 0)
			note_factory_mac(probe);
	}
}

void wq_mac_net_tick(void)
{
	static const uint8_t zero[6];
	if (g_watch_started || memcmp(g_saved_factory, zero, 6) || netctl_state() != 3)
		return;
	WqMacStatus st;
	memset(&st, 0, sizeof(st));
	kmac(WQ_MAC_OP_STATUS, 0, 0, &st);
	if (!st.hooked)
		factory_from_scenet();
}

static int watch_thread(SceSize args, void *argp)
{
	static const uint8_t zero[6];
	for (int t = 0;; t++) {
		sceKernelDelayThread(g_fast ? 200 * 1000 : 1000 * 1000);
		if (g_fast && t > 300)                     /* ~60 s after boot */
			g_fast = 0;
		run_queue();
		WqMacStatus st;
		memset(&st, 0, sizeof(st));
		kmac(WQ_MAC_OP_STATUS, 0, 0, &st);    /* cheap: no hooks, no walk */
		/* Learn the console's own address once connected, whatever the mode:
		 * the Settings page shows it in Default and Randomize builds on it.
		 * Without the hooks (Default since boot) no address was ever set, so
		 * SceNet's is the console's own; with them, the kernel kept it. */
		if (!memcmp(g_saved_factory, zero, 6) && !g_job_busy && netctl_state() == 3) {
			if (!st.hooked) {
				factory_from_scenet();
			} else {
				if (g_mtx >= 0) sceKernelLockMutex(g_mtx, 1, NULL);
				if (ensure_ctx(&st) == WQ_OK)
					note_factory(&st);
				if (g_mtx >= 0) sceKernelUnlockMutex(g_mtx, 1);
			}
		}
		if (g_job_busy)
			continue;
		if (g_retry) {
			retry_tick();
			continue;
		}
		if (!st.hooked || st.powerups == g_applied_powerups || !can_send())
			continue;
		if (g_mode == 1) {
			WQ_LOGI("mac: chip powered up (%u) - %s the custom address", (unsigned)st.powerups,
			        g_fast ? "sending (before the first join)" : "re-sending");
			if (apply(g_custom, "power-up") != WQ_OK)
				g_applied_powerups = st.powerups;      /* retry_tick takes it from here */
			continue;
		}
		/* Default: the chip is back on its own address, but after a custom one
		 * the driver's copy and wlan0 still hold that until it is sent once. */
		g_applied_powerups = st.powerups;
		uint8_t f[6];
		if (st.sets && factory(f) == WQ_OK && memcmp(st.drv, f, 6)) {
			WQ_LOGI("mac: chip powered up (%u) - restoring the console's own address",
			        (unsigned)st.powerups);
			apply(f, "power-up stock");
		}
	}
	return 0;
}

/* Settings page: run a 'mac ...' command on the watcher thread. 0, or
 * WQ_ERR_BUSY if the queue is full (the command is dropped). */
int wq_mac_queue(const char *line)
{
	watch_start();
	unsigned h = g_q_head;
	if (h - g_q_tail >= MAC_QUEUE) {
		WQ_LOGW("mac: command queue full - '%s' dropped", line);
		return WQ_ERR_BUSY;
	}
	int i = 0;
	for (; line[i] && i < WQ_UI_CMD_MAX - 1; i++)
		g_queue[h % MAC_QUEUE][i] = line[i];
	g_queue[h % MAC_QUEUE][i] = 0;
	g_q_head = h + 1;
	return WQ_OK;
}

/* Called from boot, :1339 and the Settings queue: the flag is taken
 * atomically, so only one caller creates the mutex and the thread. */
static void watch_start(void)
{
	if (g_mtx < 0) {                       /* created once, before any apply can run */
		SceUID m = sceKernelCreateMutex("WqMacMtx", 0, 0, NULL), none = -1;
		if (m >= 0 && !__atomic_compare_exchange_n(&g_mtx, &none, m, 0, __ATOMIC_SEQ_CST,
		                                           __ATOMIC_SEQ_CST))
			sceKernelDeleteMutex(m);           /* another caller won */
	}
	if (__atomic_exchange_n(&g_watch_started, 1, __ATOMIC_SEQ_CST))
		return;
	SceUID t = sceKernelCreateThread("WqMacWatch", watch_thread, 0x40, 0x2000, 0, 0, NULL);
	if (t < 0 || sceKernelStartThread(t, 0, NULL) < 0)
		g_watch_started = 0;
}

static int job_thread(SceSize args, void *argp)
{
	if (g_job_boot) {
		/* Send the address at a chip power-up before the first join, so the
		 * console connects once: the RX buffer preset's boot cycle if there
		 * is one, else our own (the watcher sends on the power-up). Only if
		 * the link wins anyway is it the usual drop / SET / rejoin. */
		WqMacStatus st;
		int started = 0;
		for (int i = 0; i < MAC_BOOT_WAIT_S * 5; i++) {
			if (kmac(WQ_MAC_OP_STATUS, 0, 0, &st) == WQ_OK && st.powerups > 0) {
				g_job_busy = 0;                  /* the watcher sends it */
				return sceKernelExitDeleteThread(0);
			}
			/* The preset's boot run cycles the radio only if it really
			 * can (not on a fallback to stock, an unknown image, ...). */
			int rx = g_boot_rx_cycle && rxpreset_boot_state() != 3;
			if (netctl_state() == 3 && !rx)
				break;                           /* joined first: drop / SET / rejoin */
			if (!started && !rx && radio_on()) {
				sceKernelDelayThread(1000 * 1000);
				if (netctl_state() != 3 && rxcycle_start_ex(0, 0, NULL) == WQ_OK) {
					started = 1;
					WQ_LOGI("mac: boot - radio power-cycle so the address is set before the first join");
				}
			}
			sceKernelDelayThread(200 * 1000);
		}
		g_fast = 0;
	} else {
		sceKernelDelayThread(2 * 1000 * 1000);      /* let the reply/Settings settle */
	}
	if (radio_on())
		apply(g_job_mac, g_job_boot ? "boot" : g_mode ? "custom" : "stock");
	else
		WQ_LOGI("mac: radio off - the address goes to the chip when it powers up");
	/* The setting moved on while this one ran: the watcher sends the newest. */
	const uint8_t *want = g_mode == 1 ? g_custom : g_saved_factory;
	if (memcmp(g_job_mac, want, 6))
		g_retry = 1;
	g_job_busy = 0;
	return sceKernelExitDeleteThread(0);
}

static int start_job(const uint8_t *m, int boot)
{
	watch_start();
	if (__atomic_exchange_n(&g_job_busy, 1, __ATOMIC_SEQ_CST))   /* test and set */
		return WQ_ERR_BUSY;
	memcpy(g_job_mac, m, 6);
	g_job_boot = boot;
	SceUID t = sceKernelCreateThread("WqMacJob", job_thread, 0x40, 0x2000, 0, 0, NULL);
	if (t < 0 || sceKernelStartThread(t, 0, NULL) < 0) {
		g_job_busy = 0;
		return WQ_ERR_NOT_READY;
	}
	return WQ_OK;
}

/* The console's own address, or WQ_ERR_NOT_READY. */
static int factory(uint8_t *out)
{
	static const uint8_t zero[6];
	if (memcmp(g_saved_factory, zero, 6)) {
		memcpy(out, g_saved_factory, 6);
		return WQ_OK;
	}
	WqMacStatus st;
	if (ensure_ctx(&st) != WQ_OK || !st.have_factory)
		return WQ_ERR_NOT_READY;
	note_factory(&st);
	memcpy(out, st.factory, 6);
	return WQ_OK;
}

void wq_mac_boot(int mode, unsigned m0, unsigned m1, unsigned f0, unsigned f1, int rx_cycle)
{
	g_mode = mode ? 1 : 0;
	g_boot_rx_cycle = rx_cycle;
	if (g_mode == 1) {
		WqMacStatus st;
		kmac(WQ_MAC_OP_HOOK, 0, 0, &st);    /* hooks in before the boot power-up */
		g_fast = 1;
	}
	join(g_custom, m0, m1);
	join(g_saved_factory, f0, f1);
	if (g_mode == 1)
		watch_start();                   /* Default: none until the first change */
	uint8_t probe[6];
	int why;
	if (g_mode != 1)
		return;
	{
		char t[13], *p = t;
		put_mac_sep(p, t + sizeof(t), g_custom, 0);
		if (wq_mac_parse(t, probe, &why) < 0) {      /* a damaged saved address */
			WQ_LOGW("mac: saved custom address invalid - back to stock");
			g_mode = 0;
			save_state();
			return;
		}
	}
	if (start_job(g_custom, 1) != WQ_OK)
		WQ_LOGW("mac: boot apply not started");
}

/* The address in use now: the driver's copy, or the console's own if the chip
 * has powered up since the last SET (stale); SceNet's before the driver was
 * reached; the saved own address as a last resort. */
static void in_use(const WqMacStatus *st, uint8_t out[6])
{
	static const uint8_t zero[6];
	if (st->ctx_seen && memcmp(st->drv, zero, 6)) {
		memcpy(out, st->stale ? st->factory : st->drv, 6);
		return;
	}
	SceNetEtherAddr na;
	memset(&na, 0, sizeof(na));
	if (sceNetGetMacAddress(&na, 0) >= 0 && memcmp(na.data, zero, 6))
		memcpy(out, na.data, 6);
	else
		memcpy(out, g_saved_factory, 6);
}

/* The address in use, the one the setting asks for (custom, or the console's
 * own), and 1 while a change towards it is still under way: being applied,
 * queued, waiting to retry, or waiting for a chip power-up to be handled or
 * for the radio to come on. */
static int mac_now(uint8_t use[6], uint8_t want[6])
{
	static const uint8_t zero[6];
	WqMacStatus st;
	memset(&st, 0, sizeof(st));
	kmac(WQ_MAC_OP_STATUS, 0, 0, &st);         /* reads only */
	in_use(&st, use);
	memcpy(want, g_mode == 1 ? g_custom : g_saved_factory, 6);
	if (!memcmp(want, zero, 6))
		memcpy(want, use, 6);                    /* own address not known yet */
	if (!memcmp(use, want, 6))
		return 0;
	return g_applying || g_job_busy || g_retry || g_q_tail != g_q_head ||
	       (st.hooked && st.powerups != g_applied_powerups) || !radio_on();
}

/* HUD, Custom only (0 in Default: no line): 1 and the custom address while it
 * is in use, 2 and the custom address while a change to it is under way,
 * 3 and the address in use if the custom one did not take. */
int wq_mac_hud(uint8_t mac[6])
{
	uint8_t use[6], want[6];
	if (g_mode != 1)
		return 0;
	int busy = mac_now(use, want);
	if (!memcmp(use, want, 6)) { memcpy(mac, want, 6); return 1; }
	if (busy)                  { memcpy(mac, want, 6); return 2; }
	memcpy(mac, use, 6);
	return 3;
}

/* Settings page: the address in use and whether a change is under way, into
 * the published state (WqUiState.macuse0/1, macbusy). */
void wq_mac_publish(int *use0, int *use1, int *busy)
{
	uint8_t use[6], want[6];
	unsigned w0, w1;
	*busy = mac_now(use, want);
	split(use, &w0, &w1);
	*use0 = (int)w0;
	*use1 = (int)w1;
}

/* ---- commands -------------------------------------------------------------- */

static char *put_status(char *p, char *end, const WqMacStatus *s)
{
	SceNetEtherAddr na;
	memset(&na, 0, sizeof(na));
	int nr = sceNetGetMacAddress(&na, 0);
	p = put(p, end, g_mode ? "mac: custom " : "mac: stock");
	if (g_mode) p = put_mac(p, end, g_custom);
	p = put(p, end, " | chip-now drv ");  p = put_mac(p, end, s->drv);
	p = put(p, end, " wlan0 ");
	if (s->chain == 0) p = put_mac(p, end, s->lladdr);
	else { p = put(p, end, "? (step "); p = put_u(p, end, s->chain); p = put(p, end, ")"); }
	p = put(p, end, " sceNet ");
	if (nr >= 0) p = put_mac(p, end, na.data); else p = put(p, end, "err");
	p = put(p, end, " factory ");
	if (s->have_factory) p = put_mac(p, end, s->factory); else p = put(p, end, "?");
	p = put(p, end, " | ctl ");
	p = put(p, end, s->ctl_check == 0 ? "OK" : s->ctl_check == 2 ? "ENTRY-MISMATCH"
	              : s->ctl_check == 3 ? "BACKPTR-MISMATCH" : "?");
	p = put(p, end, " powerups "); p = put_u(p, end, s->powerups);
	p = put(p, end, " sets ");     p = put_u(p, end, s->sets);
	if (!s->hooked)   p = put(p, end, " | NOT HOOKED");
	if (!s->ctx_seen) p = put(p, end, " | no driver ctx yet");
	return p;
}

int wq_mac_cmd(const char *a, char *out, int outcap)
{
	char *p = out, *end = out + outcap;
	WqMacStatus st;
	memset(&st, 0, sizeof(st));
	out[0] = 0;
	const char *arg = a;
	while (*arg && *arg != ' ') arg++;
	while (*arg == ' ') arg++;
#define IS(w) (strncmp(a, w, sizeof(w) - 1) == 0 && (a[sizeof(w) - 1] == 0 || a[sizeof(w) - 1] == ' '))

	if (!a[0] || IS("status")) {
		int r = kmac(WQ_MAC_OP_WALK, 0, 0, &st);   /* all four copies, freshly read */
		put_status(p, end, &st);
		return r;
	}
	if (IS("set") || IS("random") || IS("custom")) {
		uint8_t m[6], f[6];
		if (IS("set")) {
			int why;
			if (wq_mac_parse(arg, m, &why) < 0) {
				p = put(p, end, "mac: refused - ");
				put(p, end, k_why[why]);
				return WQ_ERR_ARG;
			}
		} else {
			if (factory(f) != WQ_OK) {
				put(p, end, "mac: the console's own address is not known yet (connect first)");
				return WQ_ERR_NOT_READY;
			}
			wq_mac_random(m, f);
		}
		g_mode = 1;
		memcpy(g_custom, m, 6);
		retry_reset();
		save_state();
		int r = start_job(m, 0);
		if (r == WQ_ERR_BUSY) {                    /* a change is still running: */
			g_retry = 1;                           /* the watcher sends this next */
			r = WQ_OK;
		}
		p = put(p, end, "mac: custom ");
		p = put_mac(p, end, m);
		put(p, end, r == WQ_OK ? " - Wi-Fi drops and rejoins" : " - saved, not applied");
		return r;
	}
	if (IS("stock")) {
		uint8_t f[6];
		int was = g_mode;
		g_mode = 0;
		retry_reset();
		save_state();
		kmac(WQ_MAC_OP_STATUS, 0, 0, &st);
		if (!was && st.sets == 0) {
			put(p, end, "mac: stock (already in use)");
			return WQ_OK;
		}
		if (factory(f) != WQ_OK) {
			put(p, end, "mac: stock saved; it applies after a restart");
			return WQ_OK;
		}
		int r = start_job(f, 0);
		if (r == WQ_ERR_BUSY) {
			g_retry = 1;
			r = WQ_OK;
		}
		p = put(p, end, "mac: stock ");
		p = put_mac(p, end, f);
		put(p, end, r == WQ_OK ? " - Wi-Fi drops and rejoins" : " - saved, not applied");
		return r;
	}
#undef IS
	put(p, end, "usage: mac status|stock|custom|random|set <addr>");
	return WQ_ERR_ARG;
}
